code4='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen=set(); comp_size={}; singletons=[]
    for r in range(h):
        for c in range(w):
            if (r,c) in seen: continue
            color=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            for cell in comp: comp_size[cell]=len(comp)
            if len(comp)==1: singletons.append(comp[0])
    global_counts=Counter(v for row in grid for v in row)
    background=max(global_counts, key=global_counts.get)
    out=[row[:] for row in grid]
    for r,c in singletons:
        neighbor_colors={grid[y][x] for y in range(max(0,r-1),min(h,r+2)) for x in range(max(0,c-1),min(w,c+2)) if (y,x)!=(r,c)}
        area_by_color={}
        for color in neighbor_colors:
            best=0
            for y0 in range(r+1):
                for y1 in range(r,h):
                    if y1-y0+1<2: continue
                    for x0 in range(c+1):
                        for x1 in range(c,w):
                            area=(y1-y0+1)*(x1-x0+1)
                            if area<=best or x1-x0+1<2: continue
                            if all((y,x)==(r,c) or grid[y][x]==color for y in range(y0,y1+1) for x in range(x0,x1+1)):
                                best=area
            if best: area_by_color[color]=best
        if area_by_color:
            best=max(area_by_color.values())
            tied=[v for v,a in area_by_color.items() if a==best]
            if len(tied)>1:
                tied.sort(key=lambda v:(v!=background, -sum(grid[y][x]==v for y,x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0<=y<h and 0<=x<w), min(comp_size[(y,x)] for y,x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0<=y<h and 0<=x<w and grid[y][x]==v)))
            out[r][c]=tied[0]
        else:
            vals=[grid[y][x] for y,x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0<=y<h and 0<=x<w]
            counts=Counter(vals); best=max(counts.values()); tied=[v for v,n in counts.items() if n==best]
            if background in tied: choice=background
            else:
                tied.sort(key=lambda v:min(comp_size[(y,x)] for y,x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0<=y<h and 0<=x<w and grid[y][x]==v))
                choice=tied[0]
            out[r][c]=choice
    return out
'''
